#pragma once

#include <string>
#include <map> // Includes C++ Map (Dictionary) to link a 'char' to its texture data
#include "glad/glad.h"
#include "glm/glm.hpp"
#include "glm/gtc/matrix_transform.hpp"

// Struct to store the physical metrics of a single letter generated by FreeType.
struct Character {
    unsigned int textureID; // The GPU ID of the texture containing this letter's image.
    glm::ivec2   size;      // Width and Height of the glyph in pixels.
    glm::ivec2   bearing;   // Distance from the origin (baseline) to the top-left of the glyph.
    unsigned int advance;   // How far to move the cursor to the right to draw the NEXT letter.
};

class TextRenderer {
public:
    TextRenderer(int screenWidth, int screenHeight); // Constructor
    ~TextRenderer(); // Destructor to clean up GPU memory

    // Loads the font using FreeType and pre-renders the alphabet into textures.
    bool init(const std::string& fontPath, unsigned int fontSize = 24);

    // Helper function that calculates the total width of a string in pixels without drawing it.
    float measureText(const std::string& text, float scale) const;

    // Renders the string of text to the screen.
    void drawText(const std::string& text, float x, float y, float scale, const glm::vec4& color);

private:
    // A dictionary linking an ASCII character (like 'A') to its pre-rendered Texture and Size data.
    std::map<char, Character> m_characters; 
    
    unsigned int m_vao           = 0; // Vertex Array Object for the text quad
    unsigned int m_vbo           = 0; // Vertex Buffer Object for the text quad
    unsigned int m_shaderProgram = 0; // The custom text shader program ID
    glm::mat4    m_projection;        // The 2D Orthographic camera matrix

    // Cached shader uniform locations (saves CPU time so we don't have to look them up every frame)
    int m_locTextColor  = -1;
    int m_locText       = -1;
    int m_locProjection = -1;

    // Helper functions to compile standard GLSL text shaders
    unsigned int compileShader(const char* src, unsigned int type);
    unsigned int linkShaderProgram(unsigned int vert, unsigned int frag);
    std::string  readFile(const std::string& path);
};